Web)"&gt;/&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Hive, Athena&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="2" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Partner with cross-functional teams to&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;optimize&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;&nbsp;data architecture and workflows&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-charstyle="Strong"&gt;Machine Learning &amp; AI Development&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="1" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Design, develop, evaluate, and deploy ML/AI models in production environments&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="2" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Build scalable ML pipelines for training, validation, deployment, and scoring&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="3" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Develop advanced predictive models&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;&nbsp;and&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;recommendation engines&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="4" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Optimize&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;&nbsp;model performance through experimentation, feature engineering, and ensemble techniques&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="5" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Implement automation frameworks to improve productivity and reproducibility&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-charstyle="Strong"&gt;Cloud &amp; Distributed Systems&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="1" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Leverage AWS technologies including EC2, EMR, S3, Airflow, and Athena&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="2" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Build and&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;maintain&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;&nbsp;robust workflows in distributed computing environments&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-charstyle="Strong"&gt;Analytics, Reporting &amp; Marketing Automation&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="1" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Generate client-facing&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;modeling insights dashboards&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;and&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;performance&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;reports with a strong focus on accuracy&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;,&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;consistency&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;, and&nbsp;&lt;/span&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;explainability&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="2" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Support marketing automation initiatives using Python, Snowflake, Apache Superset, and related technologies&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-charstyle="Strong"&gt;Collaboration &amp; Delivery&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="1" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Work on multiple concurrent projects in a fast-paced, high-growth environment&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="2" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Communicate complex findings clearly to both technical and non-technical stakeholders&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="o" data-font="Courier New" data-listid="13" data-list-defn-props="{"335552541":1,"335559685":1080,"335559991":360,"469769226":"Courier New","469769242":[9675],"469777803":"left","469777804":"o","469777815":"hybrid Multilevel"}" data-aria-posinset="3" data-aria-level="2"&gt;&lt;span data-contrast="auto"&gt;&lt;span data-ccp-parastyle="Normal (Web)"&gt;Mentor junior team members and contribute to best practices across the data science function&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;Required Skills:&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="1" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Strong&nbsp;expertise&nbsp;in supervised learning and advanced ML techniques (Random Forest, GBM, regression, neural networks,&nbsp;boosting and bagging methods,&nbsp;ensemble models)&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="2" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Proven experience building and productionizing ML pipelines&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="3" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Advanced Python&nbsp;proficiency&nbsp;and experience with ML libraries&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="4" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Strong data preparation and feature engineering skills&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="5" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Experience with Snowflake and distributed data systems&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="6" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Working knowledge of Unix and shell scripting&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="6" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="7" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;Strong analytical thinking, attention to detail, and communication skills&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;

QUALIFICATIONS:
&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/p&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="7" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="1" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;MSc/MS in a quantitative field with&nbsp;4+ years of experience&lt;/span&gt;&nbsp;&lt;br&gt;&lt;strong&gt;&lt;span data-contrast="auto"&gt;or&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li data-leveltext="" data-font="Symbol" data-listid="7" data-list-defn-props="{"335552541":1,"335559685":720,"335559991":360,"469769226":"Symbol","469769242":[8226],"469777803":"left","469777804":"","469777815":"multilevel"}" data-aria-posinset="2" data-aria-level="1"&gt;&lt;span data-contrast="auto"&gt;BSc with&nbsp;7+ years of relevant experience&lt;/span&gt;&lt;span data-ccp-props="{"134233117":true,"134233118":true}"&gt;&nbsp;&lt;/span&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;WHO WE ARE&nbsp;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;Zeta Global (NYSE: ZETA) is the AI-Powered Marketing Cloud that leverages advanced artificial intelligence (AI) and trillions of consumer signals to make it easier for marketers to acquire, grow, and retain customers more efficiently. Through the Zeta Marketing Platform (ZMP), our vision is to make sophisticated marketing simple by unifying identity, intelligence, and omnichannel activation into a single platform – powered by one of the industry’s largest proprietary databases and AI. Our enterprise customers across multiple verticals are empowered to personalize experiences with consumers at an individual level across every channel, delivering better results for marketing programs. Zeta was founded in 2007 by David A. Steinberg and John Sculley and is headquartered in New York City with offices around the world. To learn more, go to &lt;a href="https://www.zetaglobal.com"&gt;www.zetaglobal.com&lt;/a&gt;.&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;ZETA IN THE NEWS!&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;a id="menur45ro" class="fui-Link ___1q1shib f2hkw1w f3rmtva f1ewtqcl fyind8e f1k6fduh f1w7gpdv fk6fouc fjoy568 figsok6 f1s184ao f1mk8lai fnbmjn9 f1o700av f13mvf36 f1cmlufx f9n3di6 f1ids18y f1tx3yz7 f1deo86v f1eh06m1 f1iescvh fhgqx19 f1olyrje f1p93eir f1nev41a f1h8hb77 f1lqvz6u f10aw75t fsle3fq f17ae5zn" href="https://zetaglobal.com/press/?cat=press-releases" target="_blank"&gt;https://zetaglobal.com/press/?cat=press-releases&lt;/a&gt;&nbsp;&lt;/p&gt;

&lt;p&gt;&nbsp;&lt;/p&gt; &lt;p style="text-align: center;"&gt;&lt;strong&gt;Senior Frontend Engineer&lt;/strong&gt;&lt;/p&gt; &lt;p style="text-align: left;"&gt;&lt;strong&gt;Summary&lt;/strong&gt;&lt;/p&gt; &lt;p style="text-align: left;"&gt;As a Senior Frontend Engineer, you bring extensive experience in building modern, scalable web applications using contemporary frontend technologies. You are passionate about creating intuitive, high-performance user interfaces, collaborating with cross-functional teams, and driving best practices in frontend architecture, code quality, and user experience across web platforms.&lt;/p&gt; &lt;p style="text-align: left;"&gt;&lt;strong&gt;Key

RESPONSIBILITIES:
&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li style="text-align: left;"&gt;Translate business and product requirements into scalable, high-quality frontend architecture and core components for a marketing automation platform.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Design, develop, and maintain efficient, reusable, and reliable application code aligned with product and UI/UX requirements.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Own and drive the development of key product components, including prototyping, feature implementation, and UI translation of new requirements.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Collaborate closely with Product Managers, Designers, Backend Engineers, and QA to deliver cohesive and high-quality product experiences.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Ensure product quality through rigorous code reviews, unit testing, debugging, and continuous optimisation of existing web applications.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Actively participate in Agile/Scrum processes, document technical requirements, and contribute to technical decisions and implementation strategies.&lt;/li&gt; &lt;/ul&gt; &lt;p style="text-align: left;"&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li style="text-align: left;"&gt;We are seeking exceptional talent with strong academic credentials and a solid foundation in computer science, with a good understanding of scalable web application architecture and frontend system design.&lt;/li&gt; &lt;li style="text-align: left;"&gt;The candidate should have at least 6 years of experience building scalable and robust frontend applications, using modern Java Script technologies such as Java Script/Type Script and React JS technology&lt;/li&gt; &lt;li style="text-align: left;"&gt;A Bachelor’s degree in Computer Science or a related field from a university where the primary language of instruction is English is strongly preferred.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Strong communication skills in a large, distributed development team environment are essential.&lt;/li&gt; &lt;/ul&gt; &lt;p style="text-align: left;"&gt;&lt;strong&gt;Qualification: &lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li style="text-align: left;"&gt;Bachelor’s or Master’s degree in Computer Science or a related field.&lt;/li&gt; &lt;li style="text-align: left;"&gt;5–8 years of experience building modern web applications with strong expertise in frontend development.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Strong hands-on experience with React JS, along with deep proficiency in Java Script/Type Script, HTML, and CSS.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Ability to design and develop scalable frontend features, leveraging modern technologies and best engineering practices.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Solid understanding of frontend architecture, code quality, and maintainable component-based design.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Demonstrated working experience with, and quick adoption of, AI tools and AI-based development practices.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Experience contributing to design discussions, architecture decisions, and technical reviews.&lt;/li&gt; &lt;li style="text-align: left;"&gt;Self-driven, well-organized, and able to work effectively both independently and collaboratively within cross-functional teams&lt;/li&gt; &lt;/ul&gt; &lt;p style="text-align: left;"&gt;&lt;strong&gt;Company Summary&lt;/strong&gt;&lt;/p&gt; &lt;p style="text-align: left;"&gt;Zeta Global is a data-powered marketing technology company with a heritage of innovation and industry leadership. Founded in 2007 by entrepreneur David A. Steinberg and John Sculley, former CEO of Apple Inc and Pepsi-Cola, the Company combines the industry’s 3rd largest proprietary data set (2.4B+ identities) with Artificial Intelligence to unlock consumer intent, personalize experiences and help our clients drive business growth.&lt;/p&gt; &lt;p style="text-align: left;"&gt;Our technology runs on the Zeta Marketing Platform, which powers ‘end to end’ marketing programs for some of the world’s leading brands. With expertise encompassing all digital marketing channels – Email, Display, Social, Search and Mobile – Zeta orchestrates acquisition and engagement programs that deliver results that are scalable, repeatable and sustainable.&lt;/p&gt; &lt;p style="text-align: left;"&gt;Zeta Global is an Equal Opportunity/Affirmative Action employer and does not discriminate on the basis of race, gender, ancestry, color, religion, sex, age, marital status, sexual orientation, gender identity, national origin, medical condition, disability, veterans status, or any other basis protected by law.&lt;/p&gt; &lt;p style="text-align: left;"&gt;Pursuant to the San Francisco Fair Chance Ordinance, we will consider for employment qualified applicants with arrest and conviction records.&lt;/p&gt; &lt;p style="text-align: left;"&gt;Zeta Global Recognized in Enterprise Marketing Software and Cross-Channel Campaign Management Reports by Independent Research Firm&lt;/p&gt; &lt;p style="text-align: left;"&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt;

&lt;p&gt;Greetings From Zeta Global !!&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;

EDUCATION:
&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;B.S. or M.S. in Computer Science or a related field.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Experience:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;8+ years of experience with UI Automation tools such as Selenium, and API automation works.&lt;/li&gt; &lt;li&gt;5+ years of experience working with Python and/or J2EE technology or equivalent OO paradigm.&lt;/li&gt; &lt;li&gt;Experience with automating test validation either via API or through databases using Snowflake, HIVE, or AWS Athena is highly desirable.&lt;/li&gt; &lt;li&gt;Web application testing experience required both in frontend and backend validations.&lt;/li&gt; &lt;li&gt;Experience working in a fast-paced technology environment.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Technical Skills:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;Knowledge and experience with Robot Framework and its libraries using Python.&lt;/li&gt; &lt;li&gt;Strong proficiency in Python programming.&lt;/li&gt; &lt;li&gt;Knowledgeable in Git workflows like branching, merging, and conflict resolution.&lt;/li&gt; &lt;li&gt;Solid understanding of SDLC and Agile testing methodologies.&lt;/li&gt; &lt;li&gt;Experience with Atlassian tools such as Jira and Confluence preferred.&lt;/li&gt; &lt;li&gt;Knowledge and experience with Kafka, Elasticsearch, and SQL/No SQL databases such as Aerospike, Thrift, CI, and AWS is highly desirable.&lt;/li&gt; &lt;li&gt;Knowledge of other test automation frameworks such as Selenium, Appium, or Cucumber is a plus.&lt;/li&gt; &lt;li&gt;Experience working with container-based solutions is a plus.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Soft Skills:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;Strong communication and interpersonal skills.&lt;/li&gt; &lt;li&gt;Excellent problem-solving, critical thinking, and analytical skills.&lt;/li&gt; &lt;li&gt;Ability and desire to learn new skills and take on new tasks.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;

RESPONSIBILITIES:
&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Testing and Automation:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;Perform automated tests covering both frontend/UI and backend/API tests, analyze results, and report defects.&lt;/li&gt; &lt;li&gt;Continuously improve the test automation strategy to enhance test coverage and efficiency.&lt;/li&gt; &lt;li&gt;Proactively involve in the development of automation frameworks to satisfy business requirements as well as improve the performance and usability of the framework.&lt;/li&gt; &lt;li&gt;Automate tests to ensure functional requirements and performance KPIs are met.&lt;/li&gt; &lt;li&gt;Ensure high product quality through rigorous functional and API level tests.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Collaboration and Mentorship:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;Understand business requirements independently and cooperatively.&lt;/li&gt; &lt;li&gt;Mentor and guide other QA engineers on best practices in test automation.&lt;/li&gt; &lt;li&gt;Collaborate with cross-functional teams to integrate automated tests into the CI/CD pipeline.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Development and Documentation:&lt;/strong&gt;&lt;/li&gt; &lt;ul&gt; &lt;li&gt;Architect, design, and implement a reliable and scalable automation framework for a real-world machine learning platform.&lt;/li&gt; &lt;li&gt;Develop comprehensive test plans covering business use cases and test cases.&lt;/li&gt; &lt;li&gt;Identify, record, document thoroughly, and track bugs.&lt;/li&gt; &lt;li&gt;Perform thorough regression testing when bugs are resolved.&lt;/li&gt; &lt;/ul&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Company Summary&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;Zeta Global is a NYSE listed data-powered marketing technology company with a heritage of innovation and industry leadership. Founded in 2007 by entrepreneur David A. Steinberg and John Sculley, former CEO of Apple Inc and Pepsi-Cola, the Company combines the industry’s 3rd largest proprietary data set (2.4B+ identities) with Artificial Intelligence to unlock consumer intent, personalize experiences and help our clients drive business growth.&lt;/p&gt; &lt;p&gt;Our technology runs on the Zeta Marketing Platform, which powers ‘end to end’ marketing programs for some of the world’s leading brands. With expertise encompassing all digital marketing channels – Email, Display, Social, Search and Mobile – Zeta orchestrates acquisition and engagement programs that deliver results that are scalable, repeatable and sustainable.&lt;/p&gt; &lt;p&gt;Zeta Global is an &lt;em&gt;Equal Opportunity/Affirmative&lt;/em&gt; Action employer and does not discriminate on the basis of race, gender, ancestry, color, religion, sex, age, marital status, sexual orientation, gender identity, national origin, medical condition, disability, veterans status, or any other basis protected by law.&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Zeta Global Recognized in Enterprise Marketing Software and Cross-Channel Campaign Management Reports by Independent Research Firm&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;a href="https://www.forbes.com/sites/shelleykohan/2024/06/19/amazon-partners-with-zeta-global-to-deliver-gen-ai-marketing-automation/"&gt;&lt;strong&gt;https://www.forbes.com/sites/shelleykohan/2024/06/19/amazon-partners-with-zeta-global-to-deliver-gen-ai-marketing-automation/&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt; &lt;p&gt;&lt;a href="https://www.cnbc.com/video/2024/05/06/zeta-global-ceo-david-steinberg-talks-ai-in-focus-at-milken-conference.html"&gt;&lt;strong&gt;https://www.cnbc.com/video/2024/05/06/zeta-global-ceo-david-steinberg-talks-ai-in-focus-at-milken-conference.html&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt; &lt;p&gt;&lt;a href="https://www.businesswire.com/news/home/20240904622808/en/Zeta-Increases-3Q%E2%80%9924-Guidance"&gt;&lt;strong&gt;https://www.businesswire.com/news/home/20240904622808/en/Zeta-Increases-3Q%E2%80%9924-Guidance&lt;/strong&gt;&lt;/a&gt;&lt;/p&gt; &lt;p&gt;&lt;a href="https://www.prnewswire.com/news-releases/zeta-global-opens-ai--data-labs-in-san-francisco-and-nyc-300945353.html"&gt;&lt;em&gt;https://www.prnewswire.com/news-releases/zeta-global-opens-ai--data-labs-in-san-francisco-and-nyc-300945353.html&lt;/em&gt;&lt;/a&gt;&lt;/p&gt; &lt;p&gt;&lt;em&gt;&lt;a href="https://www.prnewswire.com/news-releases/zeta-global-recognized-in-enterprise-marketing-software-and-cross-channel-campaign-management-reports-by-independent-research-firm-300938241.html"&gt;https://www.prnewswire.com/news-releases/zeta-global-recognized-in-enterprise-marketing-software-and-cross-channel-campaign-management-reports-by-independent-research-firm-300938241.html&lt;/a&gt;&lt;/em&gt;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt;

&lt;p&gt;Zeta Global is seeking a &lt;strong&gt;Senior Manager / Associate Director&lt;/strong&gt; to join the &lt;strong&gt;Data Cloud Applications&lt;/strong&gt; team and lead the development, planning, and delivery of next-generation Intelligence Solutions within the Zeta Marketing Platform (ZMP). Zeta’s Data Cloud transforms billions of data signals into actionable intelligence that drives meaningful marketing and advertising outcomes for enterprise brands.&lt;/p&gt; &lt;p&gt;This is a high-visibility, high-impact role focused on building &lt;strong&gt;visualization-driven, AI-powered intelligence applications&lt;/strong&gt; that serve as critical assets in enterprise engagements and drive platform adoption and usage. The ideal candidate is a seasoned Saa S product leader with strong execution discipline, cross-functional leadership capabilities, and a deep understanding of how large-scale data and intelligent automation can be translated into intuitive, decision enabling experiences.&lt;strong&gt; &lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;

RESPONSIBILITIES:
&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;&lt;strong&gt;Lead the end-to-end development&lt;/strong&gt; of high-visibility Data Cloud intelligence applications within ZMP, transforming large-scale, multi-source data signals into intuitive, enterprise ready visualization and decision experiences.&lt;/li&gt; &lt;li&gt;&lt;strong&gt;Define product vision and MVP scope&lt;/strong&gt; aligned to business objectives and platform adoption goals; plan phased releases that continuously enhance client value and user engagement.&lt;/li&gt; &lt;li&gt;Author clear and comprehensive PRDs, scope functional and non-functional requirements, and manage execution across the full product development lifecycle — from ideation through release and iteration.&lt;/li&gt; &lt;li&gt;&lt;strong&gt;Partner closely with global cross-functional teams&lt;/strong&gt; including Design, Front-End Engineering, Backend/Data Engineering, Analytics, Automation, AI, and QA to architect scalable, high-quality applications within ambitious timelines.&lt;/li&gt; &lt;li&gt;&lt;strong&gt;Drive the integration of AI-native capabilities&lt;/strong&gt; powered by &lt;strong&gt;Athena by Zeta™&lt;/strong&gt;, such as automated intelligence generation, contextual summaries, and conversational data exploration — ensuring outputs are accurate, explainable, and grounded in governed data.&lt;/li&gt; &lt;li&gt;Own execution discipline across concurrent initiatives by proactively managing dependencies, mitigating risks, and ensuring timely delivery in coordination with scrum and program management functions.&lt;/li&gt; &lt;li&gt;Act as a liaison between cross-functional teams and senior leadership, providing transparency into progress, trade-offs, and release plans while advocating for resources and removing roadblocks.&lt;/li&gt; &lt;li&gt;Support post-launch adoption and usage by partnering with GTM teams, participating in client demonstrations, tracking performance metrics, and incorporating stakeholder feedback into iterative enhancements.&lt;/li&gt; &lt;li&gt;Help prioritize application development in alignment with the broader roadmap, while mentoring junior team members and fostering accountability, quality standards, and execution rigor within the team.&nbsp;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Qualifications/Skills needed:&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;7+ years of experience managing Saa S products, preferably in B2B or enterprise environments.&lt;/li&gt; &lt;li&gt;&lt;strong&gt;High-agency leader&lt;/strong&gt; with the ability to make sound, data-informed decisions in ambiguous, fast-paced environments.&nbsp;&lt;/li&gt; &lt;li&gt;Strong growth mindset with a track record of identifying gaps, driving improvements, and delivering measurable impact.&lt;/li&gt; &lt;li&gt;Proven ability to operate with agility, effectively re-prioritize, and adapt to evolving business needs and technology trends.&lt;/li&gt; &lt;li&gt;Hands-on experience building and managing technology products across the full development lifecycle.&lt;/li&gt; &lt;li&gt;Solid understanding of &lt;strong&gt;data analysis and data visualization &lt;/strong&gt;principles, with experience guiding teams on analytical approaches and delivering compelling data-driven storytelling.&lt;/li&gt; &lt;li&gt;Familiarity with AI-enabled product experiences such as automated insight generation and conversational interfaces, and an understanding of responsible AI integration within enterprise applications.&lt;/li&gt; &lt;li&gt;Strong knowledge of the digital marketing and advertising ecosystem and how data and technology drive customer engagement and outcomes.&lt;/li&gt; &lt;li&gt;Strong leadership and mentoring skills.&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;About Zeta&nbsp;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;Zeta Global is a leading AI-powered marketing technology company that enables enterprise brands to acquire, grow, and retain customers through intelligent, data-driven engagement. At the center of its innovation is the Zeta Marketing Platform (ZMP), which unifies customer data, identity, and advanced analytics to transform billions of data signals into actionable marketing intelligence and measurable business outcomes.&lt;/p&gt; &lt;p&gt;Publicly traded on the New York Stock Exchange (NYSE: ZETA), Zeta is redefining modern marketing with &lt;strong&gt;Athena by Zeta™&lt;/strong&gt;, a superintelligent, conversational agent embedded in ZMP that personalizes the marketer’s workspace, surfaces platform-generated insights through natural dialogue and recommends next-best actions to help brands accelerate and optimize their marketing outcomes.&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Know more about Zeta:&lt;/strong&gt; &lt;a href="https://zetaglobal.com/press-news/"&gt;https://zetaglobal.com/press-news/&lt;/a&gt;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;PEOPLE &amp; CULTURE AT ZETA&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;Zeta considers applicants for employment without regard to, and does not discriminate on the basis of an individual’s sex, race, color, religion, age, disability, status as a veteran, or national or ethnic origin; nor does Zeta discriminate on the basis of sexual orientation, gender identity or expression.&nbsp;&nbsp;&lt;/p&gt; &lt;p&gt;We’re committed to building a workplace culture of trust and belonging, so everyone feels invited to bring their whole selves to work. We provide a forum for employees to celebrate, support and advocate for one another. Learn more about our commitment to diversity, equity and inclusion here:&nbsp; &lt;a id="menur45rm" class="fui-Link ___1q1shib f2hkw1w f3rmtva f1ewtqcl fyind8e f1k6fduh f1w7gpdv fk6fouc fjoy568 figsok6 f1s184ao f1mk8lai fnbmjn9 f1o700av f13mvf36 f1cmlufx f9n3di6 f1ids18y f1tx3yz7 f1deo86v f1eh06m1 f1iescvh fhgqx19 f1olyrje f1p93eir f1nev41a f1h8hb77 f1lqvz6u f10aw75t fsle3fq f17ae5zn" href="https://zetaglobal.com/blog/a-look-into-zetas-ergs/" target="_blank"&gt;https://zetaglobal.com/blog/a-look-into-zetas-ergs/&lt;/a&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;ZETA IN THE NEWS!&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;a id="menur45ro" class="fui-Link ___1q1shib f2hkw1w f3rmtva f1ewtqcl fyind8e f1k6fduh f1w7gpdv fk6fouc fjoy568 figsok6 f1s184ao f1mk8lai fnbmjn9 f1o700av f13mvf36 f1cmlufx f9n3di6 f1ids18y f1tx3yz7 f1deo86v f1eh06m1 f1iescvh fhgqx19 f1olyrje f1p93eir f1nev41a f1h8hb77 f1lqvz6u f10aw75t fsle3fq f17ae5zn" href="https://zetaglobal.com/press/?cat=press-releases" target="_blank"&gt;https://zetaglobal.com/press/?cat=press-releases&lt;/a&gt;&nbsp;&lt;/p&gt;

&lt;p style="text-align: center;"&gt;&lt;span style="text-decoration: underline;"&gt;&lt;strong&gt;Senior Systems Engineer&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt; &lt;p style="text-align: left;"&gt;&lt;br&gt;&lt;strong&gt;Overview&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;We are seeking a &lt;strong&gt;Senior Systems Engineer&lt;/strong&gt; to support and enhance the infrastructure that underpins our global business operations. This role involves maintaining and improving enterprise-level systems, including data center operations, hardware platforms, virtualization, backups and recovery, operating systems, networking, and security.&lt;/p&gt; &lt;p&gt;The ideal candidate will have deep experience in enterprise infrastructure, be self-driven, and capable of independently leading projects from concept to completion. In addition to maintaining existing systems, this role will focus on modernizing and automating infrastructure to improve scalability and performance.&lt;/p&gt; &lt;p&gt;This is a global role that requires collaboration across time zones and includes participation in a 24x7 support rotation with occasional on-call responsibilities.&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Deploy and manage hardware (including gray market systems) in enterprise data centers with assistance from on-site personnel.&lt;/li&gt; &lt;li&gt;Design, implement, and migrate to modern private cloud infrastructure.&lt;/li&gt; &lt;li&gt;Establish and maintain configuration management using Foreman, Puppet Enterprise, and Ansible for Linux environments.&lt;/li&gt; &lt;li&gt;Enhance automated build and deployment pipelines for physical and virtual machines.&lt;/li&gt; &lt;li&gt;Create configuration roles and automation code using tools like Ansible and Puppet.&lt;/li&gt; &lt;li&gt;Develop scripts to automate daily tasks for the Systems Engineering team.&lt;/li&gt; &lt;li&gt;Perform advanced troubleshooting for hardware, Linux, and Windows systems in large-scale environments.&lt;/li&gt; &lt;li&gt;Lead and plan infrastructure projects independently.&lt;/li&gt; &lt;li&gt;Provide subject matter expertise in designated technical areas; contribute to technical discussions and architecture decisions.&lt;/li&gt; &lt;li&gt;Advise on data center best practices, including power configuration, HVAC, and rack design.&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;Required Qualifications&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;10+ years of Linux/Unix administration (Solaris, AIX, or other flavors)&lt;/li&gt; &lt;li&gt;3+ years of Open Stack engineering and administration&lt;/li&gt; &lt;li&gt;5+ years of VMWare or equivalent Engineering and Administration&lt;/li&gt; &lt;li&gt;5+ years of scripting experience with Bash, Perl, Ruby, Python, etc.&lt;/li&gt; &lt;li&gt;3–5 years of experience with system monitoring tools (Check_MK, Nagios, Solar Winds)&lt;/li&gt; &lt;li&gt;3–5 years of hands-on hardware management (Dell, Super Micro, HP)&lt;/li&gt; &lt;li&gt;2–3 years of experience with Puppet for configuration management&lt;/li&gt; &lt;li&gt;5+ years of experience using Microsoft Office (Word, Excel, Outlook, Teams)&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;Preferred Qualifications&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;1–2 years of storage administration (EMC, Net App, 3PAR, Hitachi)&lt;/li&gt; &lt;li&gt;1–2 years of experience with F5 load balancers&lt;/li&gt; &lt;li&gt;2–4 years of public or hybrid cloud experience (AWS, Azure, Rackspace)&lt;/li&gt; &lt;li&gt;2–3 years of application development experience (Java, C++, C#/VB.NET, PHP, HTML, Java Script)&lt;/li&gt; &lt;li&gt;1–2 years of CI/CD experience (Jenkins, Team City, etc.)&lt;/li&gt; &lt;li&gt;2+ years with Ansible AWX or Tower&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;Candidate Profile&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Strong communication and interpersonal skills&lt;/li&gt; &lt;li&gt;Skilled at mentoring and leading technical discussions (including whiteboarding sessions)&lt;/li&gt; &lt;li&gt;Excellent documentation skills, particularly using wikis and diagramming tools like Visio or Lucidchart&lt;/li&gt; &lt;li&gt;Ability to take direction while also contributing ideas for environment improvements&lt;/li&gt; &lt;li&gt;Bachelor’s degree in computer science or a related field (or equivalent experience)&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;&lt;u&gt;Digital Graphic Designer&lt;/u&gt;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Summary:&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;Zeta’s Marketing Operations is comprised of over 50 individuals who provide world class operational support to the stakeholders and clients of Zeta using multiple in-house and commercial performance marketing tools. Our Campaign Operations team is looking for a &lt;strong&gt;Digital Graphic Designer &lt;/strong&gt;in our Hyderabad office&lt;strong&gt; &lt;/strong&gt;to support our in-house Creative Team who loves to create visual stories that help people engage with brands in the digital marketing space. &nbsp;The ideal candidate is eager to learn, open-minded, and interested in being part of a team that creates stunning visual support for our client’s and their respective campaigns. Attention to detail, combined with a strong working knowledge of design-related applications, is essential.&lt;strong&gt;&lt;br&gt;&lt;br&gt;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Essential

RESPONSIBILITIES:
&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Contribute to the development of creative concepts, translating them into visual and interactive form&lt;/li&gt; &lt;li&gt;Match strategic direction with appropriate design results for the digital and web-based marketing initiatives while providing quality assurance on creative deliverables&lt;/li&gt; &lt;li&gt;Familiarity with designing for multiple formats such as email, display, social, web and mobile responsive/cross-platform&lt;/li&gt; &lt;li&gt;Exhibit an awareness of current web design practices and issues of cross-browser compatibility&lt;/li&gt; &lt;li&gt;Build and maintain a team rapport with production managers, content developers and all other Creative and Campaign Operations team personnel&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&nbsp;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Essential Competencies:&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Excellent communication skills and fluent in English (both written and verbal)&lt;/li&gt; &lt;li&gt;Ability to take creative direction and produce highly engaging designs that show a strong attention to detail in a fast-paced team environment&lt;/li&gt; &lt;li&gt;Excellent graphic design, layout and typography skills with strong, clean visuals&lt;/li&gt; &lt;li&gt;Proficiency in Adobe Creative Suite programs (specifically Photoshop, Illustrator, XD)&lt;/li&gt; &lt;li&gt;Familiarity and prior experience working with Figma and Sketch&lt;/li&gt; &lt;li&gt;Knowledge of front-end development experience such as HTML/CSS is a plus&lt;/li&gt; &lt;li&gt;Grasp of AI applications and UI/UX design processes or methodology, preferred&lt;/li&gt; &lt;li&gt;Experience with photo-retouching and logo design and illustration&lt;/li&gt; &lt;li&gt;Strong design portfolio &lt;strong&gt;(please provide link with resume)&lt;/strong&gt;&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;&nbsp;&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Desired Characteristics:&lt;/strong&gt;&lt;/p&gt; &lt;ul&gt; &lt;li&gt;Bachelor’s degree in design or a related field&lt;/li&gt; &lt;li&gt;5+ years of relevant design experience in a digital agency, media company, advertising agency, production studio, creative services environment, etc.&lt;/li&gt; &lt;li&gt;Strong collaboration, time management and multi-tasking skills&lt;/li&gt; &lt;li&gt;Experience in a fast-paced service environment&lt;/li&gt; &lt;li&gt;Comfortable with abbreviated development cycles and flexible with shifting priorities&lt;/li&gt; &lt;/ul&gt; &lt;p&gt;&lt;strong&gt;Company Summary:&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;Zeta Global is a NYSE listed data-powered marketing technology company with a heritage of innovation and industry leadership. Founded in 2007 by entrepreneur David A. Steinberg and John Sculley, former CEO of Apple Inc and Pepsi-Cola, the Company combines the industry’s 3rd largest proprietary data set (2.4B+ identities) with Artificial Intelligence to unlock consumer intent, personalize experiences and help our clients drive business growth.&lt;/p&gt; &lt;p&gt;Our technology runs on the Zeta Marketing Platform, which powers ‘end to end’ marketing programs for some of the world’s leading brands. With expertise encompassing all digital marketing channels – Email, Display, Social, Search and Mobile – Zeta orchestrates acquisition and engagement programs that deliver results that are scalable, repeatable and sustainable.&lt;/p&gt; &lt;p&gt;Zeta Global is an &lt;em&gt;Equal Opportunity/Affirmative&lt;/em&gt; Action employer and does not discriminate on the basis of race, gender, ancestry, color, religion, sex, age, marital status, sexual orientation, gender identity, national origin, medical condition, disability, veterans status, or any other basis protected by law.&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Zeta Global Recognized in Enterprise Marketing Software and Cross-Channel Campaign Management Reports by Independent Research Firm&lt;/strong&gt;&lt;/p&gt; &lt;p&gt;&lt;a href="https://protect.checkpoint.com/v2/_